CREATE TABLE IF NOT EXISTS "Usuarios" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"email" VARCHAR NOT NULL,
	"senha" VARCHAR(255) NOT NULL,
	"Nivel_de_acesso" VARCHAR(20) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Responsavel" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL,
	"nome" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id", "usuario_id")
);

CREATE TABLE IF NOT EXISTS "Aluno" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"turma" VARCHAR(255) NOT NULL,
	"numero_matricula" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Autorizado" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"grau_parental" VARCHAR(255) NOT NULL,
	"cpf" VARCHAR(11) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Movimentacao" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"aluno_id" INTEGER NOT NULL,
	"data" DATE NOT NULL,
	"horario" TIME NOT NULL,
	"pessoa_que_retirou" INTEGER NOT NULL,
	PRIMARY KEY("id", "aluno_id")
);

CREATE TABLE IF NOT EXISTS "Movimentacao_log" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL,
	"alteracap_realizada" VARCHAR(255) NOT NULL,
	"data_horario" TIMESTAMP NOT NULL,
	PRIMARY KEY("id", "usuario_id")
);

ALTER TABLE "Responsavel"
ADD FOREIGN KEY("usuario_id") REFERENCES "Usuarios"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "Movimentacao_log"
ADD FOREIGN KEY("usuario_id") REFERENCES "Usuarios"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "Movimentacao"
ADD FOREIGN KEY("aluno_id") REFERENCES "Aluno"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;